import { validateLevel } from '../core/LevelLoader';
import type { LevelData } from '../core/types';
import mechanicsTest from './mechanics-test.json';

// Campaign levels are src/levels/levelNN.json (generated by tools/gen-levels.mjs).
const campaignFiles = import.meta.glob<{ default: unknown }>('./level[0-9][0-9].json', { eager: true });

const campaign: Record<string, LevelData> = {};
for (const [path, mod] of Object.entries(campaignFiles).sort(([a], [b]) => a.localeCompare(b))) {
  const lv = validateLevel(mod.default);
  if (!path.endsWith(`/${lv.id}.json`)) throw new Error(`level id ${lv.id} does not match file ${path}`);
  campaign[lv.id] = lv;
}

export const LEVELS: Record<string, LevelData> = {
  ...campaign,
  'mechanics-test': validateLevel(mechanicsTest),
};

/** Order of the normal campaign: level01, level02, … */
export const CAMPAIGN: readonly string[] = Object.keys(campaign).sort();

/** The level that follows `id` in the campaign, or null if `id` is the last one (or not in it). */
export function nextCampaignLevel(id: string): string | null {
  const i = CAMPAIGN.indexOf(id);
  return i >= 0 && i < CAMPAIGN.length - 1 ? CAMPAIGN[i + 1]! : null;
}
